// This file exercises the real mechanism end to end, without the game:
//
//	a synthetic 1280x720 screenshot (testdata/rock_bar.png, generated by
//	testdata/gen_fixture.py) is served by a custom controller, the project's
//	resource bundle is loaded (including the OCR models), and the pipeline node
//	PickLeastRock is run for real. What is under test:
//
//	  1. OCR on the five ROIs -> counts -> argmin -> OverrideNext actually routes
//	     the task into the expected cave node;
//	  2. when nothing can be read, the task FAILS (red cross) instead of falling
//	     back to some default cave — the requirement behind「读不到必须报错」.
//
// The five cave nodes are overridden to DirectHit+DoNothing so that only the
// routing is asserted, not the game's own OCR of the cave entrances.

const rockBarFixture = "agent/rock-picker/testdata/rock_bar.png"
const rockBarBlankFixture = "agent/rock-picker/testdata/rock_bar_blank.png"

